    },
    {
      "question_id": "Q5",
      "question": "Who are the 'related people' that receive the shared result, and through what channel is that result communicated to them?",
      "answer": "Relevant parties tend to be looped in somehow, through whatever communication approach seems appropriate at the time."
    },
    {
      "question_id": "Q6",
